    <div class="hero-bg"></div>
    <div class="hero-mesh"></div>
    <div class="floating-orb orb-1"></div>
    <div class="floating-orb orb-2"></div>
    <div class="page-hero-content" :class="{ visible: pageVisible }">
      <span class="section-tag">Contact</span>
      <h1 class="page-title">お問い合わせ</h1>
      <p class="page-subtitle">アプリ開発・DevOps・Web制作のご相談はお気軽にどうぞ</p>
    </div>
  </section>

  <!-- ===== Form Section ===== -->
  <section class="form-section">
    <v-container>
      <div class="form-wrap" :class="{ visible: pageVisible }">
        <v-form v-model="valid" @submit.prevent="handleSubmit">

          <div class="field-group">
            <label class="field-label">件名 <span class="required">必須</span></label>
            <v-text-field
              v-model="form.subject"
              :rules="[required]"
              placeholder="例：アプリ開発のご相談"
              variant="outlined"
              density="comfortable"
              hide-details="auto"
              class="dark-field"
            />
          </div>

          <div class="field-group">
            <label class="field-label">会社名・団体名</label>
