          </div>

          <div class="submit-wrap">
            <button
              type="submit"
              class="submit-btn"
              :class="{ loading: isLoading }"
              :disabled="!valid || isLoading"
            >
              <v-icon v-if="isLoading" size="18" class="spin">mdi-loading</v-icon>
              <v-icon v-else size="18">mdi-send-outline</v-icon>
              {{ isLoading ? '送信中...' : '送信する' }}
            </button>
          </div>

        </v-form>
      </div>

