<script setup>
import { ref, reactive, onMounted } from "vue";
import axios from "axios";

const pageVisible = ref(false);
const valid = ref(false);
const dialog = ref(false);
const isLoading = ref(false);
const errorMessage = ref("");

const FORM_URL =
  "https://docs.google.com/forms/u/2/d/e/1FAIpQLSfJElGFNeRBlUdVLKNarXmU32rRFQ6cgV46DPqwNbHcZCrztw/formResponse";

const ENTRY_MAP = {
  subject: "entry.71885439",
  organization: "entry.60286043",
  name: "entry.1775750585",
  mail: "entry.812097791",
  content: "entry.1398375857",
};

const INITIAL_FORM = () => ({
  subject: "",
  organization: "",
  name: "",
  mail: "",
  content: "",
});

const form = reactive(INITIAL_FORM());

const snsLinks = [
  {
    title: "代表のX",
    subtitle: "DMからお気軽にお問い合わせください",
    icon: "mdi-alpha-x-box",
    href: "https://twitter.com/KeitaKozuka",
    color: "#e2e8f0",
  },
  {
    title: "代表のFacebook",
    subtitle: "DMからお気軽にお問い合わせください",
    icon: "mdi-facebook",
    href: "https://www.facebook.com/keita.kozuka",
    color: "#60a5fa",
  },
];

const required = (v) => !!v || "必須項目です";
const emailRule = (v) => /.+@.+\..+/.test(v) || "メールアドレスの形式が正しくありません";

async function handleSubmit() {
  if (!valid.value) return;
  isLoading.value = true;
  errorMessage.value = "";

  const params = new URLSearchParams();
  for (const key in form) {
    params.append(ENTRY_MAP[key], form[key]);
  }

  try {
    await axios.get(`${FORM_URL}?${params.toString()}`);
    Object.assign(form, INITIAL_FORM());
    dialog.value = true;
  } catch (error) {
    // Google Forms は CORS エラーを返すが送信は成功している
    if (error.response) {
      errorMessage.value = "送信に失敗しました。しばらくしてからもう一度お試しください。";
    } else {
      // ネットワークエラー（CORSブロック）は送信成功とみなす
      Object.assign(form, INITIAL_FORM());
      dialog.value = true;
    }
  } finally {
    isLoading.value = false;
  }
}

onMounted(() => {
  setTimeout(() => (pageVisible.value = true), 200);
});
</script>

